package io.github.diodeme.ji.relay.protocol;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Objects;

/** Version and framing contract shared by Relay, Host, and Client transports. */
public final class RelayProtocol {
    public static final String RELEASE_VERSION = "0.1.0";
    public static final int CURRENT_HOST_PROTOCOL = 1;
    public static final int PREVIOUS_HOST_PROTOCOL = 0;
    public static final int MAX_FRAME_BYTES = 1024 * 1024;
    public static final int MAX_BUFFERED_FRAMES = 256;
    public static final int MAX_BUFFERED_BYTES = 4 * 1024 * 1024;
    public static final String NOISE_SUITE = "Noise_XX_25519_ChaChaPoly_SHA256";

    private RelayProtocol() {}

    public static boolean supportsHostProtocol(int version) {
        return version == CURRENT_HOST_PROTOCOL || version == PREVIOUS_HOST_PROTOCOL;
    }

    /** Canonical route metadata bound as Noise associated data on every transport frame. */
    public static byte[] routeAssociatedData(Route route, Direction direction, long counter, long keyEpoch) {
        Objects.requireNonNull(route, "route");
        Objects.requireNonNull(direction, "direction");
        if (counter < 0 || keyEpoch < 0) throw new IllegalArgumentException("counter and key epoch must be non-negative");
        byte[] routeId = route.routeId().getBytes(StandardCharsets.UTF_8);
        byte[] hostId = route.hostId().getBytes(StandardCharsets.UTF_8);
        byte[] deviceId = route.deviceId().getBytes(StandardCharsets.UTF_8);
        if (routeId.length > 255 || hostId.length > 255 || deviceId.length > 255) {
            throw new IllegalArgumentException("route identity is too long");
        }
        return ByteBuffer.allocate(4 + 1 + routeId.length + 1 + hostId.length + 1 + deviceId.length + 1 + 8 + 8)
                .putInt(CURRENT_HOST_PROTOCOL)
                .put((byte) routeId.length).put(routeId)
                .put((byte) hostId.length).put(hostId)
                .put((byte) deviceId.length).put(deviceId)
                .put((byte) direction.ordinal())
                .putLong(counter)
                .putLong(keyEpoch)
                .array();
    }

    public enum Direction { CLIENT_TO_HOST, HOST_TO_CLIENT }

    public record Route(String tenantId, String routeId, String hostId, String deviceId) {
        public Route {
            tenantId = required(tenantId, "tenantId");
            routeId = required(routeId, "routeId");
            hostId = required(hostId, "hostId");
            deviceId = required(deviceId, "deviceId");
        }
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
